levels.solution:
#include "rover.h"

int main(void) {
    // 1. 速さと辺の長さを決める
    double speed = 0.6;
    double side = 1.5;
    // 2. 4 つの辺を走る
    for (int i = 0; i < 4; i++) {
        motor(speed, speed);
        wait(side / (1.1 * speed));
        stop();
        motor(0.25, -0.25);
        wait(0.46);
        stop();
    }
    return 0;
}

