levels.solution:
#include "rover.h"

// 1. LiDAR で止まる関数を作る
void forward_until(double near) {
    motor(0.7, 0.7);
    while (1) {
        double d = lidar();
        if (d >= 0 && d < near) {
            break;
        }
    }
    stop();
}

// 2. 呼んで走る
int main(void) {
    forward_until(0.22);
    return 0;
}

levels.py_equiv:
def forward_until(near):
    motor(0.7, 0.7)
    while True:
        d = lidar()
        if d is None:
            d = -1
        if d >= 0 and d < near:
            break
    stop()

forward_until(0.22)

